/// The table for a family in a variant, matched on the identity of its regular
/// advance table the way `font_variants.tableFor` is: a `Family` is a value and
/// its `glyphs` slice is the one thing unique to it.
pub fn tableFor(family: font_metrics.Family, variant: font_variants.Variant) Table {
    const rows = [_]struct { []const font_metrics.Glyph, font_variants.Variant, Table }{
        .{ font_metrics.system_ui.glyphs, .regular, .{ .advances = &advances_regular_system_ui, .text_weight = &weight_regular_system_ui, .tracking = &tracking_regular_system_ui } },
        .{ font_metrics.system_ui.glyphs, .bold, .{ .advances = &advances_bold_system_ui, .text_weight = &weight_bold_system_ui, .tracking = &tracking_bold_system_ui } },
        .{ font_metrics.system_ui.glyphs, .italic, .{ .advances = &advances_italic_system_ui, .text_weight = &weight_italic_system_ui, .tracking = &tracking_italic_system_ui } },
        .{ font_metrics.system_ui.glyphs, .bold_italic, .{ .advances = &advances_bold_italic_system_ui, .text_weight = &weight_bold_italic_system_ui, .tracking = &tracking_bold_italic_system_ui } },
    };
    for (rows) |row| {
        if (row[0].ptr == family.glyphs.ptr and row[1] == variant) {
            return row[2];
        }
    }
    return .{};
}
